import{_ as t,a as r,b as i,c as o,d as a}from"./chunks/b8e2943d56c19bc70664.D3Jvqtn0.js";import{_ as n,C as s,o as m,c as g,j as e,a as h,E as u,a5 as d}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"百万美元产品：如何打包与营销你的知识","description":"","frontmatter":{"title":"百万美元产品：如何打包与营销你的知识","originalTitle":"The $1 Million Product: How To Package & Market Your Knowledge","date":"2025-02-01","originalUrl":"https://thedankoe.com/letters/the-1-million-product-how-to-package-market-your-knowledge/","minutes":22,"sourceHash":"6d8ede871b7187c4ba738280e65accd14ae6b16b3261fb8f5e575c9c0a6d2081","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-1-million-product-how-to-package-market-your-knowledge/"}]]},"headers":[],"relativePath":"letters/the-1-million-product-how-to-package-market-your-knowledge.md","filePath":"letters/the-1-million-product-how-to-package-market-your-knowledge.md"}'),c={name:"letters/the-1-million-product-how-to-package-market-your-knowledge.md"};function k(f,p,b,_,w,x){const l=s("ArticleMeta");return m(),g("div",null,[p[0]||(p[0]=e("h1",{id:"百万美元产品-如何打包与营销你的知识",tabindex:"-1"},[h("百万美元产品：如何打包与营销你的知识 "),e("a",{class:"header-anchor",href:"#百万美元产品-如何打包与营销你的知识","aria-label":'Permalink to "百万美元产品：如何打包与营销你的知识"'},"​")],-1)),u(l),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/Er2s-CFoZSo?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你的脑子里困着10万美元。</p><p>或者，它就散落在你的Google Drive、Notion，或者Kortex里。</p><p>重点是：</p><p>你拥有技能、兴趣，以及某种可以打包成产品的专业知识——这个产品能在你睡觉的时候帮你赚钱。</p><p>你在这篇信里学到的东西，将决定你作为一个创作者能取得多大的成功。</p><p>但这篇信不只是关于打造产品。</p><p>其中还涉及很多东西，比如：</p><ul><li>如何找到一个超高利润的想法</li><li>如何制定营销策略并在失败中迭代</li><li>如何把一个无聊的产品定位成人们无法忽视的东西</li><li>一个无法拒绝的报价的5个要素</li><li>即便你从未写过落地页，也能学会怎么写</li><li>如何真正把产品做出来，以及如何收款</li><li>最后，如何发布产品，让它不会闲置在那里积灰（也不会浪费你的时间）</li></ul><p>事情是这样的……</p><p>如果你想赚取独立的收入，<em>同时</em>掌控自己的时间，你需要一个产品。</p><p>这应该是显而易见的。</p><p>然而，大多数人都跟我一样。你从客户项目开始做起。你开始看到一些成绩。你的时间被吞噬掉。最糟糕的是，你意识到自己有多讨厌为别人的项目工作。</p><p>你辞掉工作，是因为你讨厌那份工作，对吧？</p><p>你想写作。</p><p>你想探索自己的兴趣。</p><p>你想专注于自己的手艺，但现在你又回到了生存模式，从一张发票到另一张发票地活着，而不是从一份薇水到下一份薈水。</p><p>但一旦你拥有一个不需要你投入时间或劳力就能赚取可观收入的产品，那么赚到10万美元，就只是坚持和迭代的问题了。</p><p>一旦你意识到，如果你能赚到1美元，只要你有一个能够以一人之力扩展到那个规模的<em>产品</em>，你就能赚到100万美元——这会让人感到无比解脑。</p><p>如果你想组建一个团队来完成价值100万美元以上的客户项目，那随你便，但即便如此，为什么不打造一个既能给你的营收锦上添花，<em>又</em>能为你的客户业务带来更多热络潛在客户的产品呢？</p><p>在开始之前，请明白，这不是什么快速致富的胡说八道。</p><p>我打造产品的第一年，赚了大约1万美元。</p><p>第二年是10万美元。</p><p>然后是15万。然后是80万。然后是400万。</p><p>然后我才觉得有足够的信心来资助Kortex，也才有了做这件事所需的受众。</p><p>如果你坚持这条路数年（并且拒绝回到你曾想要逃离的生活），你会看到成功。</p><p>这篇会很长，因为它是一堂产品与营销的大师课。</p><p>两者都是不可跳过的关键技能。</p><h2 id="如何找到一个百万美元的想法——该打造什么产品" tabindex="-1">如何找到一个百万美元的想法——该打造什么产品 <a class="header-anchor" href="#如何找到一个百万美元的想法——该打造什么产品" aria-label="Permalink to &quot;如何找到一个百万美元的想法——该打造什么产品&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>给你来点脑洞大开的事：</p><p>你已经购买过一个百万美元级别的产品了。</p><p>事实上，你已经买过成百上千个，甚至更多。</p><p>你知道这意味着什么吗？</p><p>这意味着你可能想得太多了。</p><p>这意味着，如果你理解了我在这篇信里要讲的东西，大多数想法都能被做到100万美元。</p><p>现在，我假设这是你的第一个产品，而你是个新手。</p><p>面向未来的AI时代，最好遵循这样的进阶路径：</p><ul><li>把打造受众当作一个免费且高杠杆的流量来源</li><li>在你的兴趣或专业领域中成为一个权威</li><li>从一个可以快速测试的“个人系统”数字产品开始</li><li>坚持并迭代，直到达到10万美元以上</li><li>然后，既然你已经积累了大量的数据和成果，把这个系统转化成类似软件或实体产品的东西</li></ul><p>这里最大的问题是，“<em>什么是‘个人系统’产品？</em>”</p><p>简单来说，这是你把任何一个想法转化为独一无二东西的方式。一种AI无法复制或取代的东西——因为它是可以在过程中使用AI的。</p><p>这可以以自由职业服务、教练服务、教育产品或软件的形式来实现。</p><p>举个例子，我的《2小时写作者》课程并不是在教写作。它教的是我自己的个人系统——我写什么、我怎么写、以及我为什么写。它把写作——这件事本身太无聊或太学术——<em>定位</em>成一种对那些<em>像我过去一样的人</em>来说既有吸引力又有价值的东西（参见：<a href="/letters/how-to-create-your-niche-of-one-become-nicheless">你就是那个细分领域</a>）。</p><p>我写一篇通讯，把它拆解成社交媒体帖子，把这些帖子交叉发布到各个平台上，每天写作时间不到2小时，就能在所有平台上建立起受众。</p><p>我可以轻松地把这个转化成一项面向个人品牌的自由职业服务，帮他们处理内容创作。我也可以教人们如何以一对一的教练服务形式来实施这套方法，面向创始人和高管，不只是创作者，因为打造受众是一件如此重要的事情。</p><p>但既然我们想避免客户项目并掌控自己的时间，我们剩下的两个选项就是<em>教育产品和软件产品</em>。</p><p>多亏了像Cursor和Lovable这样的工具，如今打造软件对普通人来说更容易上手了。它仍然需要时间去学习，如果你想做得体面，还是得学不少编程知识，但打造一个网页应用或移动应用现在是完全可能的，我每天都能在X上看到这种情况发生。</p><p>问题是，你仍然需要理解营销和报价创建。打造下一个待办事项应用，如果没有一个能让它显得独一无二的<em>个人系统</em>，你不会走得太远。</p><p>在我看来，未来几年内，教育产品仍然是最好的起点。而且就像Cursor对编程的帮助那样，等<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>的AI功能在接下来几周上线后，你也可以用它来帮助写作。</p><p>教育产品的形式包括：</p><ul><li>课程</li><li>社群</li><li>训练营（Cohorts）</li></ul><p>这些都以一个个人系统为核心，并配有模板，这些模板同样可以借助Kortex来提供。</p><p>你知道的，就是那些排满Alex Hormozi的产品组合的那类产品。</p><p>那些被人们喜欢用负面眼光去钉在墙上的“信息产品”——好像教育不是你成长发展中最重要的一环，好像教育不是能让你为一个学校已经跟不上的未来做好准备的东西。</p><p>一个<em>好</em>的教育产品，任何一天都可能比实体产品或软件多10倍地改变一个人的生活。</p><p>创作者是去中心化的教师。他们<em>就是</em>互联网上的新学校体系。创作者——不是内容创作者，而是那些创造自己人生的人——是那些开辟新道路、并传递那些能让你抓住新机会的秘传信息的人。</p><p>只要人们还买书，他们就会买课程。让自己的思维只看到教育产品的半张图，跟你觉得课程有多蠢一样愚蠢。你不会去抱怨这个世界上有大约1亿2986万4880本书（其中大多数很差，因为任何人都能在键盘上打字……），所以如果你无法接受信息产品，那你的日子会很难过。</p><p>“但Dan！人们只是在教他们自己在做的事情！”</p><p>没错，可不是吗。那正是市场想要的东西，而这实际上也是<em>任何人</em>真正有资格去教的唯一东西。</p><p>关于这个我可以整天应对反对意见，但我会让你自己想清楚，别被某个反大师灌输进你脑子里的那些老生常谈的信念左右（顺便说一句，他们教育你说教育是坏事，而你竟然连钱都没为这个“教育”付过！）</p><p>教育产品利润超高，价值超高。这是完美的组合。你打造一次，就能想卖多少次卖多少次。</p><p>所以，这就是这篇信接下来要聚焦的内容。</p><h3 id="把你在做的事情转化成一个产品想法" tabindex="-1">把你在做的事情转化成一个产品想法 <a class="header-anchor" href="#把你在做的事情转化成一个产品想法" aria-label="Permalink to &quot;把你在做的事情转化成一个产品想法&quot;">​</a></h3><p>最好的教育产品是那些：</p><ul><li>解决一个具体的痛点</li><li>给人们一个能获得结果的系统</li><li>为执行该系统所涉及的一切提供清晰的说明</li></ul><p>首先，我们需要确定你想要打造的产品的主题。然后我们再来讲有趣的部分——如何营销这个产品。</p><p>想一个你至少有一些经验的领域。</p><p>一个你花时间去研究或在生活中实践过的东西。</p><p>你还<em>不需要</em>个人系统这一部分。只需要主题。</p><p>这里有一份清单，可能能激发一些想法。</p><ul><li>写作</li><li>视频剪辑</li><li>演讲</li><li>社交动态</li><li>人际关系与恋爱</li><li>生产力</li><li>网页设计或开发</li><li>人工智能</li><li>心理健康</li><li>举重</li><li>跑步</li><li>营养</li><li>更快地学习</li><li>知识管理</li><li>理财</li><li>拿到工作面试</li></ul><p>简单地想一件你水平高于平均水准的事情，把它写下来。</p><p>第二步，我们需要在那个主题内研究产品<em>和</em>想法。</p><p>我们的目标是找到<em>行之有效的东西</em>和<em>你能做得更好的东西</em>之间的交集。</p><p>写下至少10-20个产品或想法。</p><p>你要怎么找到它们？</p><ul><li>在像Masterclass、Udemy或Skillshare这样的课程网站上搜索你的主题</li><li>在Reddit上搜索课程评价，比如在健康主题里搜“最好的训练项目”</li><li>翻遍你关注的账号，加入他们的邮件列表，找出他们在网站和营销漏斗里卖的产品</li><li>回想你过去买过的产品，把它们重新翻出来</li><li>在该主题内找到X账号，用Twemex查看他们表现最好的推文，搜索与你主题相关的关键词，保存那些可以用作产品或营销想法的帖子</li><li>在该主题内找到YouTube账号，按最受欢迎筛选他们的视频，把可能转化成产品的热门视频标题写下来</li></ul><p>假设你想以社交动态为兴趣打造一门生意。</p><p>你可以去Charisma On Command这个YouTube频道，研究他们的视频标题，挑出几个明显比其他视频表现更好的。</p><p><img src="'+r+'" alt=""></p><p>如果你看看他们最热门的视频，你能立刻看出，变得有趣、自信、不自我怀疑，是人们<em>真正想要</em>的东西。</p><p>你可以围绕这一点打造一个产品，用自己的方式重新演绎其中不少视频主题，并且相当有信心这个产品会做得不错。</p><p>在你调研的过程中，把这些想法都安全地保存在某个地方。</p><p>现在你手上有了一份成功的产品和营销想法清单，你可以把它们组合、拓展、简化，或者做得独一无二。接下来我们就来做这件事。</p><p>对于你找到的课程，把它们买下来。</p><p>这时候别跟我省这点钱。</p><p>如果你不知道该怎么搭建一个产品的结构，那你需要用其中几个作为灵感参考点。</p><p>你现在还不需要确切地知道你想创造什么。</p><h2 id="如何营销并打造产品" tabindex="-1">如何营销并打造产品 <a class="header-anchor" href="#如何营销并打造产品" aria-label="Permalink to &quot;如何营销并打造产品&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>大多数人浪费2-3个月的时间去打造一个产品，结果却从未发布，或者更糟——从来没卖出去一单。</p><p>我们要做的完全相反。</p><p>你要在<em>真正开始打造产品之前</em>就赚到钱。</p><p>这样一来，如果你没赚到钱，你可以迅速转向，重新再试一次。</p><p>一旦你挖到金子，你就全力以赴，用2-3周的时间把它打造出来，然后发布一个成功的产品。</p><p>这也是教育产品更优越的又一个原因。</p><ol><li>你可以快速测试和迭代。</li><li>你可以把它们转变成软件或其他产品。</li><li>如果做得好，它们对购买者是真正有帮助的。</li></ol><p>换句话说，大多数产品都应该<em>从</em>教育产品<em>开始</em>，而大多数创始人只要加入某种形式的教育内容——即便只是一本电子书——就能创造出一个新的收入渠道。</p><h3 id="选择你的目标人物画像" tabindex="-1">选择你的目标人物画像 <a class="header-anchor" href="#选择你的目标人物画像" aria-label="Permalink to &quot;选择你的目标人物画像&quot;">​</a></h3><p>人们在这一部分卡住的次数实在太多了。</p><p>让我们把它简单化。</p><p>你需要一个目标人物画像——也就是你把产品定位给谁——这样你的营销才能具体、可感知。就这么简单。</p><p>问题是，实际上还存在一个<em>更大</em>的市场，那些人也会对你的营销产生共鸣。尤其是当你用社交媒体做营销时。你不希望定位<em>太</em>具体，否则你的内容就传不到更多人手里。</p><p>就我个人而言，我认为你应该从这两个选项中选择：</p><ol><li>以你自己或过去的自己为目标。</li><li>以有钱的人为目标（创始人、高管、拥有高薪工作的人）。</li></ol><p>以有钱人为目标的问题在于，你往往不理解他们。你无法和他们产生共鸣。这会渗透到你的营销中。不过，对那些曾与这类人合作过，或在社交媒体上关注了大量这类人的人来说，这是个不错的选择。</p><p>现在你只需要这些。</p><p>一个关于你想定位谁的模糊想法。</p><h3 id="五步创造他们无法拒绝的报价" tabindex="-1">五步创造他们无法拒绝的报价 <a class="header-anchor" href="#五步创造他们无法拒绝的报价" aria-label="Permalink to &quot;五步创造他们无法拒绝的报价&quot;">​</a></h3><p>你不是从产品开始的。</p><p>你是从营销开始的。</p><p>因为如果你把营销做对了，你就可以<em>围绕有效的东西</em>来打造产品。</p><p>基于好的营销来打造产品，比基于烂产品去做营销，要容易得多。</p><p>现在，拿出你的主题，以及你收集的所有想法，把这些写下来：</p><p><strong>1）大问题</strong></p><p>这是需要被牢牢确定下来的最重要的事情。</p><p>与该主题相关的<em>最紧迫的大问题</em>是什么？</p><p>人们现在处于什么位置，如果他们不改变，那会导向何处？</p><p>这一个问题是如何分裂成100个更多的问题的？</p><p>问题是他们转变的起点。</p><p>这个问题应该是</p><ul><li><strong>能引起共鸣的</strong>——他们必须能够<em>感受</em>并体验到这个问题。</li><li><strong>相关的</strong>——这个问题必须是重要且值得解决的。</li><li><strong>有研究支撑的</strong>——你必须确保自己不是在凭空捏造这个问题。</li></ul><p>大多数最紧迫的问题都落在健康、财富和关系这几个类别之内。</p><p>所以如果你的主题是<strong>举重训练</strong>，问题可能是以下几种：</p><ul><li><strong>健康示例</strong>——没有抗阻训练，你更容易患上慢性疾病，并且随着年龄增长行动会变得困难。</li><li><strong>财富示例</strong>——如果你的外形不好，人们不会尊重你，因为你的身体反映了你的自律和承诺。你更不可能获得机会、晋升，以及高价值人群的信任。</li><li><strong>关系示例</strong>——你缺乏走上前去和陌生人交谈的自信，或者你在配偶面前脱掉上衣时感到不安，这导致糟糕的性生活，并在关系的其他方面引发小问题。</li></ul><p>令人惊讶的是，这里最紧迫的问题并不是与健康相关的。它与被视为高价值、从而获得更好的机会和关系相关。</p><p>如果我们想进一步放大这个问题（你应该这么做），你会谈到缺乏社交机会如何导致孤独感。这会影响你的心理健康，让你在生活的其他任何领域都更难自律行事。你陷入某个特定的工作和环境中，却完全不知道自己为什么走不出来。</p><p>顺便提一句，在第一轮头脑风暴之后，这些都不会是完美的。</p><p>这种营销策略是你在阅读更多书籍、内容、听有声书，以及和有这个问题的人交谈的过程中不断精炼出来的东西。</p><p>把这些想法当作社交媒体帖子来测试也很有帮助。你获得的互动越多，就越有可能说明这是一个值得纳入你营销中的好点子。</p><p><strong>2）期望的结果</strong></p><p>如果大问题是人们的起点，那么期望的结果就是转变的另一端。</p><p>也就是说，如果你没有确定好问题（找到正确的想法需要一些时间），你的大部分营销都会崩溃。这也是为什么你应该建立受众群体的另一个原因，这样你就可以在内容中免费测试这些想法。为此可以使用<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>。</p><p>如果我们的问题总体上是缺乏自信、以及别人不认为你有价值，那么总体上期望的结果就是拥有一个能赢得尊重的身体。</p><p>现在，我们需要再次让它变得更能引起共鸣、更相关，并且有研究支撑。</p><p>人们究竟想要什么？<strong>他们为什么想要它？</strong></p><p>对男性来说，他们想要清晰可见的腹肌、还不错的下颌线、宽阔的肩膀，并且在和别人交谈或脱衣服时对自己的身体感到自信。</p><p>对女性来说，我不太能代表她们发言，但我猜她们想要沙漏型身材、漂亮的臀部、可见的腹肌，并且<em>感觉</em>“性感”、有魅力。她们想要自己的男人为她们倾倒。</p><p>你可以把这个和一个巨大的好处配对起来，回答“为什么？”这个问题。</p><p>为什么男性想要清晰可见的腹肌？</p><p>为什么女性想要丰满的臀部？</p><p>记住，这里很多具体性都源自你的目标人物画像。</p><p><strong>3）可信的时间框架</strong></p><p>时间框架能给你的营销增加强大的驱动力。</p><p>30天。</p><p>3-6个月。</p><p>6周。</p><p>2小时。</p><p>它们帮助让你的产品变得具体可感。它们是一个参照点，能激发读者的欲望。</p><p>时间框架还有助于压缩你放入产品中的内容。很多人只是把自己知道的一切全都塞进一个产品里，而不是只放入那些真正对解决问题、达到期望结果有价值的东西。</p><p>在创建你的个人系统之后，你可能需要回来重新调整这一部分。</p><p><strong>4）个人系统</strong></p><p>你用来克服痛点并达到结果的个人系统，正是让你的产品独一无二的地方。</p><p>你可以照搬一个有效的产品的营销方式，把他们的系统换成你自己的，这样可能也会卖得非常好。这正是大多数产品所做的，因为这正是大多数人想要的。人们想要<em>你做事的方式。</em></p><p>你如何创建一个个人系统？</p><p>你去实验。在你自己身上，或者在愿意帮助你、并符合你目标人物画像的其他人身上。（如果你是新手，这也能给你带来一些结果，可以用作社会认同的证明。）</p><p>以下是你要做的：</p><ol><li>打开类似 Kortex 这样的工具，把它写下来</li><li>记住<strong>问题</strong>和<strong>结果</strong></li><li>写出他们在这个<strong>时间框架</strong>内需要采取的步骤清单</li><li>这些步骤应该涵盖与达到该结果相关的<em>一切</em>内容（例如举重训练，通常还需要涉及营养方面）</li><li>在这段时间框架内，用自己或你的目标人物画像来测试它</li><li>写下可以改进的地方</li><li>重写步骤清单并再次测试</li><li>重复这个过程，直到它能为更多人带来结果</li></ol><p>然后，给你的系统起个名字。</p><p>对于像举重训练或健康这样的领域，你会经常看到这种情况。</p><p>间歇性禁食（Intermittent Fasting）就是一个个人系统，后来发展成了一个被世界上很大一部分人认可的术语。</p><p>Stronglifts 5×5 是一个个人系统，现在已经成为大多数健身房新手的“首选”方案。</p><p>如果你能把营销的其他方面融入其中，比如 2 Hour Writer 里的“2小时”，它就会变得更加强大。</p><p>你的个人系统会让人们觉得“这终于能解决我的问题了！”</p><p><strong>4.5）教育</strong></p><p>如果你正在创建一个教育产品，你需要为人们需要知道的内容创建一个课程大纲或框架。</p><p>你可以把这个系统给他们，但如果他们不理解与之相关的一切，那帮助不会很大。</p><p>除了你的个人系统之外，还要列出人们为了最好地使用这个系统需要了解的基础知识、步骤和技能。</p><p><strong>5）功能与好处</strong></p><p>大多数人<em>只</em>列出他们产品的功能。</p><p>但那没有说服力。</p><p>人们不关心产品本身，他们关心的是产品如何改变他们的生活。这是营销101的基础知识，但即使是最资深的营销人员也会在这里栽跟头。（我们都会忘记，都需要提醒自己回归基础）。</p><p>当你列出这样的功能时：</p><ul><li>5周训练计划</li><li>包含20个食谱的食谱书</li><li>学习促进胸肌增长的前5大动作</li></ul><p>把它们和一个引人入胜的好处配对起来，或者干脆用好处<em>完全替换</em>掉那个乏味的功能：</p><ul><li>5周计划，让你走进健身房时确切知道该做什么（不再感到迷茫！）</li><li>包含20种饱腹又低卡的食物的食谱书，让你能吃得饱饱的又没有负罪感。</li><li>促进胸肌增长的前5大动作，让你不再浪费数年时间却练不出撑破衬衫的胸肌。</li></ul><p>从这里开始，把你个人系统和教育内容中的所有功能都提取出来。</p><p>把它们列出来。</p><p>给它们加上好处。</p><p>所有这些都是必要的，因为它们将成为一个高转化率落地页的构建模块。</p><p><strong>6）交付机制</strong></p><p>让我们用一个新例子，回顾一下我们所学的一切。</p><ul><li><strong>主题</strong>——生产力</li><li><strong>目标人物画像</strong>——过去的我。一个18岁的年轻人，想要在学习和创业之间取得平衡</li><li><strong>大问题+负面结果</strong>——我不想要一份传统的朝九晚五工作，但我在课业上落后了，我的事业也退居次位。如果我不能长时间专注学习，也不能长时间投入事业，我就会陷在一份舒适的工作里，而想要摆脱出来会极其困难。40年后我会后悔当初没有花时间学习。</li><li><strong>期望的结果</strong>——每天12个多小时的深度专注，不靠阿德拉（adderall，一种兴奋剂药物）</li><li><strong>可信的时间框架</strong>——14天</li><li><strong>个人系统</strong>——“注意力马拉松”，一个训练你的大脑跑马拉松的训练计划</li><li><strong>教育</strong>——关于心流状态、多巴胺、工作空间布置、避免分心等等的一切内容</li></ul><p>我知道这是一个经过验证的想法，因为我事先在YouTube上做过调研。人们<em>想要</em>极长时间地专注。</p><p><img src="'+o+'" alt=""></p><p>现在我们有了一个初步的营销计划和报价框架，我们需要决定<em>如何</em>去<em>交付</em>这个实际的报价。</p><p>在这里，你有几个选择：</p><ul><li><strong>电子书</strong>——制作速度快，但很难定高价。</li><li><strong>邮件课程</strong>——有结构化的学习，但大多数人会中途放弃。</li><li><strong>训练营（Cohort）</strong>——一个4-8周的课程，配有电话会议和社群。每年只开放报名4次。有利于营造稀缺性和感知价值，但价格昂贵。</li><li><strong>常规课程</strong>——一个可以随时推广的常青产品，但你需要大量流量。</li><li><strong>社群</strong>——月度经常性收入 = 月度经常性工作量。更难销售，但如果你投入其中，回报会非常巨大。</li><li><strong>软件</strong>——构建耗时更长，失败几率更高，但如果你为之投入5-10年（或者迅速中了病毒式传播的头奖），回报可以非常巨大。</li></ul><p>为了让这些选项中的任何一个变得更有价值，你可以加入模板、追踪表或工作表。仅凭这一点，就能让这个教育产品值得花钱购买，而不只是去看上面那个免费视频。</p><p>我无法明确告诉你该选哪一个……但我可以告诉你,你大概会做出不止一个。</p><p>一个不错的新手进阶路径可以是这样的:</p><ul><li>先做一本27美元的电子书,聚焦在一个具体主题上,比如“一年内每天专注12小时”</li><li>把它扩展成一个更大的150美元课程中的一个模块,配上一个“专注中心”模板,帮他们规划学习和工作时段</li><li>再把它扩展成一个更全面的399美元的“活在心流中”训练营(cohort)</li></ul><p>你可以在任何地方推广那本电子书。你可以在后端邮件或YouTube视频里推广那个课程。你可以每个季度一次,在所有渠道推广那个训练营。</p><p>你的交付载体——电子书、课程、训练营等等——唯一的工作,就是去兑现你的营销和报价(offer)。</p><p>当你把第一个报价里要包含的一切都梳理清楚之后,就该赚到你的第一个1美元了。</p><h2 id="落地页、发布、再构建——顺序就是这样" tabindex="-1">落地页、发布、再构建——顺序就是这样 <a class="header-anchor" href="#落地页、发布、再构建——顺序就是这样" aria-label="Permalink to &quot;落地页、发布、再构建——顺序就是这样&quot;">​</a></h2><p>我想再强调一次,这是新手的最佳路径。</p><p>我们接下来要谈的这套方法,几乎没法用在其他任何类型的产品上。</p><p>在过去,数字产品这种东西根本不算什么。</p><p>你要花大量时间去打造一个<em>可能有效、也可能没用</em>的产品。</p><p>你把钱砸进产品开发,搭建生产和分销体系,然后才发布。</p><p>业内流传着一个统计数字,大意是大约95%的企业会在第一年内倒闭。</p><p>打造受众和数字产品这件事的关键在于,你可以<em>随时转向(pivot)</em>。</p><p>你可以每天在内容里测试想法。</p><p>你可以把那些想法转化为一套营销策略。</p><p>你可以搭建一个落地页,加上支付功能,然后开启预售。</p><p>如果不成功,你可以放弃它,再试一次,无限次尝试,直到它成功为止。</p><p>换句话说,只要你<em>坚持并不断迭代</em>,失败是不可能的。</p><p>等到你真正要把它变成一家创业公司,或者更复杂的实体产品时,你已经积累了大量数据,成功的概率会大大提高。</p><p>好了,我们的营销策略已经有了,接下来你要做的是:</p><h3 id="先做落地页" tabindex="-1">先做落地页 <a class="header-anchor" href="#先做落地页" aria-label="Permalink to &quot;先做落地页&quot;">​</a></h3><p>再重复一遍:</p><p>你要<em>先</em>在一个<a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">像Stan这样的平台上</a>做出落地页。</p><p>然后,你要<em>发布</em>这个产品。一定要告诉大家,这个产品会在某个特定日期上线。在Stan里,你可以给产品添加一个模块,给所有人明确的上线时间信息。</p><p>一旦你成交了第一笔销售,压力就来了。你已经没有退路,不能放弃了。你必须集中精力,在你公开宣布的发布日期之前,做出一个<em>真正好</em>的产品。这是一种公开的问责机制,让你没法临阵退缩。</p><p>好了,一旦你把报价的各个部分都搞定了,文案写作其实很简单。</p><p>文案写作的全部意义,就是用清晰而有说服力的方式,把这个报价呈现出来。</p><p>说服力的部分我们已经搞定了,现在需要的是结构。</p><p>实现这一点的方法有很多,我建议你自己去研究,但这里说说我自己搭建页面的结构方式:</p><p><img src="'+a+'" alt=""></p><p>再说一次,搭建和托管这些产品最好的方式,就是用一个<a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">像Stan这样的平台</a>。</p><p>这些落地页搭建起来很简单(其实就是写文字而已),而且你可以托管任何类型的数字产品。而且,你所有的链接产品都会以类似LinkTree风格的页面呈现,非常适合放在你的个人简介、帖子和newsletter里推广。</p><p><strong>标题</strong></p><p>你的主标题和副标题,应该是你整个报价中所有价值的<em>浓缩版</em>。</p><p>你的任务是,在这一部分里,把大问题、期望结果、个人系统、时间框架,以及可能的目标人群这些要素中<em>最有力的部分</em>组合起来。</p><p>对于我的效率类产品来说,标题可以是这样的:</p><p><em>不靠Adderall,每天学习12小时(附14天计划)</em></p><p>如果你想要这方面的模板,可以看看<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">Mental Monetization</a>。</p><p><strong>副标题</strong></p><p>在副标题里,你要加上其他那些要素。</p><p>因为我在主标题里只放了期望结果和时间框架,那是最有力的部分,所以我的副标题可以这样写:</p><p><em>用“注意力马拉松”系统,摆脱低薪的朝九晚五,战胜廉价多巴胺。</em></p><p>这里我把个人系统、大问题都拉了进来,还顺手加了一个高热度话题——廉价多巴胺。</p><p><strong>问题 + 放大</strong></p><p>在接下来的部分,大多数人称之为<em>导语(lead)</em>,你的任务是把大问题和负面结果呈现出来。</p><p>当你从问题入手时,你会提高读者对这个问题的意识。你要让他们相信,借助一个曾经帮助过你的系统,他们的生活是可以改变的(因为确实可以)。</p><p>我个人喜欢先用几句简短的话陈述问题,然后紧接着用一个要点列表,列出由这个问题衍生出的各种痛点。</p><p>你可以去看我任何一个落地页,就能看到这一点是怎么实践的。</p><p>如果你不知道这部分该写什么,就用你自己的故事。</p><p>你以前处于什么状态?</p><p>你为什么想要改变?</p><p>你尝试过哪些没有奏效的方法?</p><p><strong>个人系统</strong></p><p>进入落地页的下一部分,你的任务是展示你的个人系统有何不同之处。</p><p>你的故事中的转折点是什么?</p><p>你是如何发现并创造出这个个人系统的?</p><p>为什么它比市面上大多数其他方案都更好?</p><p>如果你能在这里加一张图来帮助解释这个系统,那就更好了。</p><p><strong>结果或用户评价</strong></p><p>在个人系统之后,你可以放上一些人们使用你产品获得的结果的图片。</p><p>如果你还没有用户评价,你有两个选择:</p><ul><li>免费带一些人体验你的产品,换取他们的评价</li><li>展示你自己的成果</li></ul><p>你可以用你自己的图片(比如效率或健康类主题),或者如果你的主题是像网页设计这样的数字化内容,也可以用截图。</p><p><strong>功能 + 好处</strong></p><p>这是“报价介绍”部分。</p><p>在这里,你要把他们在课程里能获得的每一样东西都拆解出来。</p><p>最简单的方式,就是用一个要点列表,列出功能和好处。</p><p>如果有帮助的话,可以把这个列表当作你在<em>导语</em>里列出的那些痛点列表的<em>反面</em>。</p><p>你之前在买过的大多数产品里,应该都见过这种形式。它就是一份清单,列出里面有什么内容+为什么他们该在意。</p><p><strong>行动号召</strong></p><p>讲完功能和好处之后,你需要促成成交。</p><p>我喜欢做一个对比。</p><p>类似“用这个产品之前的你”对比“用这个产品之后的你”,再重申一下痛点和好处。</p><p>这可以是一张图,也可以是一个简单的要点列表。</p><p>如果你用的是Stan之类的平台,让这里直接接到支付按钮上。这种情况下就跳过FAQ部分。</p><p><strong>常见问题</strong></p><p>如果你在搭建一个定制落地页——我不建议你第一次就这么做(太费时间,而且这是另一项你还得学的技能)——那就加上一份常见问题和答案的清单。</p><p>如果这些问题能够化解读者在浏览落地页全程中心里冒出来的那些疑虑,那就更好了。</p><h3 id="发布、发布、再发布" tabindex="-1">发布、发布、再发布 <a class="header-anchor" href="#发布、发布、再发布" aria-label="Permalink to &quot;发布、发布、再发布&quot;">​</a></h3><p>定一个发布日期。</p><p>从你第一次推广算起,提前3到4周。</p><p>每周都在你的newsletter里推广。</p><p>把链接放在所有地方。你的个人简介和描述里都要放。</p><p>围绕你产品所涉及的主要话题,写帖子串(threads)、做轮播图(carousels),或拍短视频(reels),或者任何你平常制作的其他类型内容。</p><p>加入一些小小的植入或行动号召,比如:“如果你正被[痛点]困扰,[产品]将在[日期]上线。”</p><p><em>每次推广时,都要用上你上面制定的营销策略里的那些要素。</em></p><p>当你距离发布还剩1到2周时,开始加大推广的频率和力度。</p><p>如果你能给预购的人提供某种早鸟折扣,会非常有帮助。</p><p>为了简洁起见,这篇信就先写到这里。</p><p>如果你想让我以后多讲讲如何推广你的报价,可以告诉我。</p><p>在那之前,你可以在<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">我的网站上</a>找到之前关于建立受众、效率和写作的信件。</p><p>感谢阅读。</p><p>——Dan</p><hr><p><a href="/en/letters/the-1-million-product-how-to-package-market-your-knowledge">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',285))])}const A=n(c,[["render",k]]);export{q as __pageData,A as default};
